// ============================================================================
// THE OFFICE: sprite atlases (generated by `pnpm sprites`).
// JSON is lazy-loaded per enabled character; PNGs are plain asset URLs.
// Every frame is a uniform cell with a shared pivot, so changing frames is
// only a background-position write.
// ============================================================================

const jsonLoaders = import.meta.glob("../../assets/office/sprites/*.json", { import: "default" });
const pngUrls = /** @type {Record<string, string>} */ (
  import.meta.glob("../../assets/office/sprites/*.png", {
    eager: true,
    query: "?url",
    import: "default",
  })
);

/**
 * @typedef {{ x: number, y: number, w: number, h: number, pivot: number[], trim: number[] }} AtlasFrame
 * @typedef {{ frames: string[], fps: number, loop: boolean }} AtlasAnimation
 */

export class Atlas {
  /** @param {string} name @param {any} json @param {string} url */
  constructor(name, json, url) {
    this.name = name;
    this.url = url;
    this.size = json.size;
    this.cell = json.cell;
    /** @type {Record<string, AtlasFrame>} */
    this.frames = json.frames;
    /** @type {Record<string, AtlasAnimation>} */
    this.animations = json.animations;
    /** @type {Record<string, string>} */
    this.views = json.views;
    this.anchors = json.anchors || {};
    this.avatar = json.avatar;
    this.metrics = json.metrics || {};
    const idle = this.frames.idle_0;
    /** height of the drawn standing sprite above the pivot (sheet px) */
    this.standHeight = idle ? idle.pivot[1] - idle.trim[1] : 160;
  }

  /** @param {string} key */
  frame(key) {
    return this.frames[key] || this.frames.idle_0;
  }

  /** @param {string} key */
  has(key) {
    return Boolean(this.frames[key]);
  }

  /** Turnaround view name -> frame key. @param {string} view */
  viewFrame(view) {
    return this.views[view] || this.views.front;
  }

  /** Cell-local anchor point (e.g. 'hand', 'handL'), or null. */
  anchor(frameKey, name) {
    const a = this.anchors[frameKey];
    return a && a[name] ? a[name] : null;
  }
}

/** Decode an image off the main thread before it's shown. @param {string} url */
export async function decodeImage(url) {
  const img = new Image();
  img.decoding = "async";
  img.src = url;
  try {
    await img.decode();
  } catch {
    // decode() can reject for cached/aborted loads; fall back to onload
    if (!img.complete) {
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
      });
    }
  }
  return img;
}

/** @param {string} name */
export async function loadAtlas(name) {
  const base = `../../assets/office/sprites/${name}`;
  const loader = jsonLoaders[`${base}.json`];
  const url = pngUrls[`${base}.png`];
  if (!loader || !url) throw new Error(`Office atlas "${name}" not found. Run \`pnpm sprites\`.`);
  const json = await loader();
  await decodeImage(url);
  return new Atlas(name, json, url);
}

/** Names of every generated atlas (debug player). */
export function availableAtlases() {
  return Object.keys(pngUrls)
    .map((k) => k.split("/").pop()?.replace(".png", "") || "")
    .filter(Boolean);
}
